/** Generated by scaffold-crud-pages. Query hooks for Students.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchStudentsList,
  fetchStudentsById,
  createStudents,
  updateStudents,
  deleteStudents,
  type FetchStudentsListParams,
} from '~/services/httpServices/studentsService';
import type { CreateStudentsRequest, UpdateStudentsRequest } from '~/types/students';

const DOMAIN = 'students';

export function useStudentsList(params?: FetchStudentsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchStudentsList(params),
  });
}

export function useStudents(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchStudentsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateStudents() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateStudentsRequest) => createStudents(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateStudents() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateStudentsRequest }) =>
      updateStudents(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteStudents() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteStudents(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
